render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(longitude = cfg$x, latitude = cfg$y), c("longitude", "latitude")); size_col <- cfg$size %||% ""; if (nzchar(size_col) && size_col %in% names(data)) { data$.mynx_size <- data[[size_col]] } else { data$.mynx_size <- 2 }; size_label <- if (nzchar(size_col) && size_col %in% names(data)) size_col else "大小"; p <- ggplot2::ggplot(data, ggplot2::aes_string(x = cfg$x, y = cfg$y)) + ggplot2::geom_point(ggplot2::aes(size = .mynx_size), colour = cfg$color %||% "#0A84FF", alpha = 0.75) + ggplot2::coord_quickmap() + ggplot2::theme_minimal(base_size = 12) + ggplot2::labs(title = cfg$title %||% NULL, x = cfg$x, y = cfg$y, size = size_label); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
